-- F1: exercise the exact ON CONFLICT target used by PostgREST.
set local role authenticated; select set_config('request.jwt.claims','{"sub":"71000000-0000-4000-8000-000000000002","role":"authenticated"}',true);
select extensions.lives_ok($$insert into public.network_problem_approaches(id,problem_id,author_user_id,summary,audience,needs) values ('75000000-0000-4000-8000-000000000002','72000000-0000-4000-8000-000000000001','71000000-0000-4000-8000-000000000002','Original approach with enough detail to exceed the fifty character minimum.','Local care teams','Help with testing') on conflict (problem_id,author_user_id) do update set summary=excluded.summary,status='active'$$,'F1 own upsert inserts');
select extensions.lives_ok($$insert into public.network_problem_approaches(id,problem_id,author_user_id,summary,audience,needs) values ('75000000-0000-4000-8000-000000000002','72000000-0000-4000-8000-000000000001','71000000-0000-4000-8000-000000000002','Updated approach with enough detail to exceed the fifty character minimum.','Local care teams','Help with testing') on conflict (problem_id,author_user_id) do update set summary=excluded.summary,status='active'$$,'F1 own upsert edits');
select extensions.is((select count(*) from public.network_problem_approaches where author_user_id='71000000-0000-4000-8000-000000000002'),1::bigint,'F1 repeated upsert keeps one row');
select extensions.matches((select summary from public.network_problem_approaches where id='75000000-0000-4000-8000-000000000002'),'^Updated','F1 updated text persisted');
set local role authenticated; select set_config('request.jwt.claims','{"sub":"71000000-0000-4000-8000-000000000003","role":"authenticated"}',true);
select extensions.lives_ok($$insert into public.network_problem_approaches(id,problem_id,author_user_id,summary,audience,needs) values ('75000000-0000-4000-8000-000000000003','72000000-0000-4000-8000-000000000001','71000000-0000-4000-8000-000000000003','Original approach with enough detail to exceed the fifty character minimum.','Local care teams','Help with testing') on conflict (problem_id,author_user_id) do update set summary=excluded.summary,status='active'$$,'F1 second author may use same problem');
with changed as (update public.network_problem_approaches set summary=repeat('x',60) where id='75000000-0000-4000-8000-000000000002' returning id) select extensions.is((select count(*) from changed),0::bigint,'F1 foreign update changes no rows');
select extensions.throws_ok($$insert into public.network_problem_approaches(id,problem_id,author_user_id,summary,audience,needs) values ('75000000-0000-4000-8000-000000000002','72000000-0000-4000-8000-000000000001','71000000-0000-4000-8000-000000000002','Original approach with enough detail to exceed the fifty character minimum.','Local care teams','Help with testing') on conflict (problem_id,author_user_id) do update set summary=excluded.summary,status='active'$$,'42501',null,'F1 forged author upsert rejected');
set local role authenticated; select set_config('request.jwt.claims','{"sub":"71000000-0000-4000-8000-000000000002","role":"authenticated"}',true);
select extensions.lives_ok($$update public.network_problem_approaches set status='withdrawn' where id='75000000-0000-4000-8000-000000000002'$$,'F1 own withdrawal works');
select extensions.is((select status from public.network_problem_approaches where id='75000000-0000-4000-8000-000000000002'),'withdrawn','F1 withdrawn status persisted');
select extensions.lives_ok($$insert into public.network_problem_approaches(id,problem_id,author_user_id,summary,audience,needs) values ('75000000-0000-4000-8000-000000000002','72000000-0000-4000-8000-000000000001','71000000-0000-4000-8000-000000000002','Original approach with enough detail to exceed the fifty character minimum.','Local care teams','Help with testing') on conflict (problem_id,author_user_id) do update set summary=excluded.summary,status='active'$$,'F1 save reactivates same row');
select extensions.is((select status from public.network_problem_approaches where id='75000000-0000-4000-8000-000000000002'),'active','F1 reactivated');
